#!/usr/bin/env node
// Generate one static HTML entry page per Markdown page, so every page has a
// real URL (/insights/my-article, no #) with its own title, description,
// Open Graph image, canonical link and structured data.
//
// Why: the site is a Docsify single-page app. Crawlers such as LinkedIn,
// Facebook and Slack do not run JavaScript and ignore anything after a #, so
// before this every shared link previewed as the home page.
//
// What it writes (all generated, do not edit by hand):
//   index.html                  home page meta + pre-rendered home content
//   <section>/index.html        one per section README   (/insights/)
//   <section>/<page>.html       one per page             (/insights/my-article)
//   404.html                    app shell for unknown URLs (Docsify shows _404.md)
//   sitemap.xml, robots.txt
//
// index.html is the template. Edit it as normal; everything outside the
// page-meta and prerender markers is copied into every generated page.
//
// Per-page metadata comes from the page's Markdown. Title is the first # heading.
// Description defaults to the first real paragraph. To set them yourself, put a
// comment at the very top of the .md file:
//
//   <!-- meta
//   description: One or two sentences, ideally under 160 characters.
//   image: /assets/images/og/my-article.png     (1200 x 627 PNG or JPG; not SVG)
//   image_alt: What the image shows.
//   author: Bella Grant
//   date: 2026-11-23
//   -->
//
// Run after adding, renaming or removing a page (CI also runs it on push):
//   npm install --no-save marked@18 && node infra/gen-pages.mjs

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
let marked;
try {
  ({ marked } = require('marked'));
} catch (e) {
  console.error('This script needs the "marked" package: npm install --no-save marked@18');
  process.exit(1);
}

// ---- Settings ---------------------------------------------------------------
const SITE = 'https://pathwayanalytics.com';          // canonical origin for every URL
const SITE_NAME = 'Pathway Analytics';
const DEFAULT_IMAGE = '/assets/images/og/default.png';
const DEFAULT_IMAGE_ALT = 'Pathway Analytics: health economics and strategic advisory';
const ORG_LOGO = 'https://mta-sts.pathwayanalytics.com/logo/Pathway%20Analytics%20Logo%20small.png';
const ARTICLE_SECTIONS = ['/insights/', '/case-studies/'];  // pages here get og:type article
const EXCLUDE = ['/pers-content', '/AGENTS', '/CLAUDE']; // routes never published as pages
const GENERATED = '<!-- GENERATED by infra/gen-pages.mjs. Edit index.html or the page\'s .md file, not this file. -->';
// -----------------------------------------------------------------------------

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');
const write = (p, s) => {
  fs.mkdirSync(path.dirname(path.join(ROOT, p)), { recursive: true });
  fs.writeFileSync(path.join(ROOT, p), s);
};

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const abs = (u) => (/^https?:\/\//.test(u) ? u : SITE + (u.startsWith('/') ? u : '/' + u));

// ---- Find pages ---------------------------------------------------------------
function walk(dir) {
  const out = [];
  for (const ent of fs.readdirSync(path.join(ROOT, dir), { withFileTypes: true })) {
    if (ent.name.startsWith('.') || ent.name === 'node_modules') continue;
    const rel = dir ? `${dir}/${ent.name}` : ent.name;
    if (ent.isDirectory()) out.push(...walk(rel));
    else if (ent.name.endsWith('.md') && !ent.name.startsWith('_')) out.push(rel);
  }
  return out;
}

function routeFor(file) {
  let r = '/' + file.replace(/\.md$/, '');
  if (r === '/README') return '/';
  if (r.endsWith('/README')) return r.slice(0, -'README'.length);
  return r;
}

function outputFor(route) {
  if (route === '/') return 'index.html';
  if (route.endsWith('/')) return route.slice(1) + 'index.html';
  return route.slice(1) + '.html';
}

// ---- Read metadata from Markdown --------------------------------------------
function parseMeta(md) {
  const m = md.match(/^\s*<!--\s*meta\s*\n([\s\S]*?)-->\s*/);
  const meta = {};
  if (!m) return { meta, body: md };
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^\s*([a-z_]+)\s*:\s*(.*?)\s*$/i);
    if (kv && kv[2]) meta[kv[1].toLowerCase()] = kv[2];
  }
  return { meta, body: md.slice(m[0].length) };
}

function plain(s) {
  return s
    .replace(/<[^>]+>/g, ' ')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/[*_`#>]/g, '')
    .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&[a-z]+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function truncate(s, n = 160) {
  if (s.length <= n) return s;
  const cut = s.slice(0, n - 1);
  return cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:.\s]+$/, '') + '…';
}

function describe(file, md) {
  const { meta, body } = parseMeta(md);
  const tokens = marked.lexer(body);
  const h1 = tokens.find((t) => t.type === 'heading' && t.depth === 1);
  const title = meta.title || (h1 ? plain(h1.text) : SITE_NAME);
  let description = meta.description;
  if (!description) {
    const para = tokens.find((t) => t.type === 'paragraph' && plain(t.text).length >= 60);
    description = para ? truncate(plain(para.text)) : `${title}, from ${SITE_NAME}.`;
  }
  let image = meta.image;
  if (!image) {
    const img = body.match(/(?:src="|!\[[^\]]*\]\()([^")\s]+\.(?:png|jpe?g|webp|gif))/i);
    if (img && !/^https?:/.test(img[1])) image = img[1];
  }
  return {
    title,
    description,
    image: abs(image || DEFAULT_IMAGE),
    imageAlt: meta.image_alt || (image ? title : DEFAULT_IMAGE_ALT),
    author: meta.author,
    date: meta.date,
    body,
  };
}

// ---- Build head tags ----------------------------------------------------------
function headTags(route, p, { noindex = false } = {}) {
  const url = SITE + route;
  const isHome = route === '/';
  const isArticle = ARTICLE_SECTIONS.some((s) => route.startsWith(s) && route !== s);
  const docTitle = isHome ? p.title : `${p.title} — ${SITE_NAME}`;

  const ld = isHome
    ? {
        '@context': 'https://schema.org',
        '@type': 'Organization',
        name: SITE_NAME,
        url: SITE,
        logo: ORG_LOGO,
        contactPoint: { '@type': 'ContactPoint', contactType: 'customer service', email: 'enquiries@pathwayanalytics.com' },
      }
    : {
        '@context': 'https://schema.org',
        '@type': isArticle ? 'Article' : 'WebPage',
        [isArticle ? 'headline' : 'name']: p.title,
        description: p.description,
        url,
        mainEntityOfPage: url,
        image: p.image,
        ...(p.date ? { datePublished: p.date } : {}),
        ...(isArticle
          ? { author: p.author ? { '@type': 'Person', name: p.author } : { '@type': 'Organization', name: SITE_NAME, url: SITE } }
          : {}),
        publisher: { '@type': 'Organization', name: SITE_NAME, url: SITE, logo: { '@type': 'ImageObject', url: ORG_LOGO } },
      };

  const t = [
    `<title>${esc(docTitle)}</title>`,
    `<meta name="description" content="${esc(p.description)}">`,
    `<meta name="robots" content="${noindex ? 'noindex, follow' : 'index, follow'}">`,
    ...(noindex ? [] : [`<link rel="canonical" href="${esc(url)}">`]),
    `<meta property="og:site_name" content="${SITE_NAME}">`,
    `<meta property="og:locale" content="en_GB">`,
    `<meta property="og:type" content="${isArticle ? 'article' : 'website'}">`,
    `<meta property="og:title" content="${esc(p.title)}">`,
    `<meta property="og:description" content="${esc(p.description)}">`,
    ...(noindex ? [] : [`<meta property="og:url" content="${esc(url)}">`]),
    `<meta property="og:image" content="${esc(p.image)}">`,
    `<meta property="og:image:alt" content="${esc(p.imageAlt)}">`,
    ...(/\/og\/[^/]+\.png$/.test(p.image)
      ? [`<meta property="og:image:width" content="1200">`, `<meta property="og:image:height" content="627">`]
      : []),
    ...(isArticle && p.date ? [`<meta property="article:published_time" content="${esc(p.date)}">`] : []),
    ...(isArticle && p.author ? [`<meta name="author" content="${esc(p.author)}">`] : []),
    `<meta name="twitter:card" content="summary_large_image">`,
    `<meta name="twitter:title" content="${esc(p.title)}">`,
    `<meta name="twitter:description" content="${esc(p.description)}">`,
    `<meta name="twitter:image" content="${esc(p.image)}">`,
    `<script type="application/ld+json">${JSON.stringify(ld).replace(/</g, '\\u003c')}</script>`,
  ];
  return t.map((l) => '  ' + l).join('\n');
}

// ---- Pre-rendered body ----------------------------------------------------------
function prerender(route, p) {
  const body = p.body
    .replace(/\{\{segment:[^}]*\}\}/g, '')
    .replace(/href="\/?#\//g, 'href="/')
    .replace(/\]\(\/#\//g, '](/');
  let html = marked.parse(body);
  // Root-relative images and links stay as they are; Docsify-style links (/page) already work.
  html = html.replace(/<!--[\s\S]*?-->/g, '');
  const crumbs = route === '/' ? '' :
    `<nav class="prerender-nav"><a href="/">${SITE_NAME}</a>` +
    (route.split('/').length > 2 && !route.endsWith('/')
      ? ` / <a href="/${route.split('/')[1]}/">${esc(route.split('/')[1].replace(/-/g, ' '))}</a>`
      : '') +
    `</nav>`;
  return `<div class="prerender">${crumbs}<article class="markdown-section">${html}</article></div>`;
}

// ---- Assemble -----------------------------------------------------------------
const template = read('index.html');
const META_RE = /(<!-- page-meta:start -->)[\s\S]*?(\n\s*<!-- page-meta:end -->)/;
const BODY_RE = /(<!-- prerender:start -->)[\s\S]*?(<!-- prerender:end -->)/;
if (!META_RE.test(template) || !BODY_RE.test(template)) {
  console.error('index.html is missing the page-meta or prerender markers.');
  process.exit(1);
}
const KEEP_META_NOTE = template.match(META_RE)[0].match(/<!-- Generated per page[\s\S]*?-->/);
const metaNote = KEEP_META_NOTE ? '\n  ' + KEEP_META_NOTE[0] : '';

function render(route, p, opts = {}) {
  let out = template
    .replace(META_RE, (_m, a, b) => `${a}${metaNote}\n${headTags(route, p, opts)}${b}`)
    .replace(BODY_RE, (_m, a, b) => `${a}${opts.body === undefined ? prerender(route, p) : opts.body}${b}`);
  out = out.replace(/^(<!DOCTYPE html>\n)(?:<!-- GENERATED[^\n]*-->\n)?/i, '$1');
  if (route !== '/') out = out.replace(/^(<!DOCTYPE html>\n)/i, `$1${GENERATED}\n`);
  return out;
}

const files = walk('').sort();
const written = new Set();
const sitemap = [];

for (const file of files) {
  const route = routeFor(file);
  if (EXCLUDE.includes(route)) continue;
  const p = describe(file, read(file));
  const out = outputFor(route);
  write(out, render(route, p));
  written.add(out);
  sitemap.push(SITE + route);
}

// 404 page: GitHub Pages serves this for unknown URLs. It loads the app, which
// shows _404.md. noindex so search engines never list it.
write('404.html', render('/404', {
  title: 'Page not found',
  description: 'The page you are looking for does not exist or may have been moved.',
  image: abs(DEFAULT_IMAGE),
  imageAlt: DEFAULT_IMAGE_ALT,
  body: '',
}, { noindex: true, body: 'Loading&hellip;' }));
written.add('404.html');

// Remove pages generated earlier whose .md has since been deleted or renamed.
(function prune(dir) {
  for (const ent of fs.readdirSync(path.join(ROOT, dir || '.'), { withFileTypes: true })) {
    if (ent.name.startsWith('.') || ent.name === 'node_modules') continue;
    const rel = dir ? `${dir}/${ent.name}` : ent.name;
    if (ent.isDirectory()) prune(rel);
    else if (ent.name.endsWith('.html') && !written.has(rel) && read(rel).includes('GENERATED by infra/gen-pages.mjs')) {
      fs.unlinkSync(path.join(ROOT, rel));
      console.log('Removed stale', rel);
    }
  }
})('');

write('sitemap.xml',
  '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
  sitemap.map((u) => `  <url><loc>${esc(u)}</loc></url>`).join('\n') + '\n</urlset>\n');
write('robots.txt', `User-agent: *\nAllow: /\n\nSitemap: ${SITE}/sitemap.xml\n`);

console.log(`Wrote ${written.size} pages, sitemap.xml and robots.txt`);
